def review(test_code):
    issues = set()
    if 'wait_for_timeout(' in test_code or 'time.sleep(' in test_code:
        issues.add('fixed-wait')
    if 'xpath=' in test_code or '("//' in test_code or "('//" in test_code:
        issues.add('xpath')
    if 'expect(' not in test_code and 'assert ' not in test_code:
        issues.add('no-assertion')
    if 'password="' in test_code or "password='" in test_code:
        issues.add('secret')
    return sorted(issues)

