coding.solution:
def coverage(criteria, cases):
    referenced = {c['requirement'] for c in cases}
    return {
        'uncovered': [r for r in criteria if r not in referenced],
        'no_oracle': [c['title'] for c in cases if not c['assertions']],
        'unknown': [c['title'] for c in cases if c['requirement'] not in criteria],
    }
